const columns = [
  { key: "kind", header: "Issue", stack: "line", render: (row) => <KindLabel kind={row.kind} /> },
  { key: "store", header: "Store", rowHeader: true, wrap: true, stack: "line", skeleton: 3,   // name over a two-line detail
    render: (row) => <StoreCell row={row} /> },
  { key: "amount", header: "At stake", align: "right", numeric: true, stack: "end",
    format: (v) => new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(v) },
  { key: "age", header: "Raised", stack: { as: "end", order: 0.5 } },
];

<DataTable
  title="Needs you"
  description={`${issues.length} open`}
  columns={columns}
  rows={issues}                       // remove a resolved issue and its row collapses
  stackBelow={640}                    // cards on phones
  loading={isLoading}
  error={loadError?.message}
  onRetry={refetch}
  emptyMessage="Nothing needs you right now."
  renderRowActions={(row, info) => (
    <Button label={row.action} variant="secondary" size="sm" fullWidth={info.stacked}
      loading={working === row.id} onClick={() => resolve(row)} />
  )}
/>

// a list beside a detail pane
<DataTable columns={requestColumns} rows={requests} selectable selected={checked} onSelectedChange={setChecked}
  activeRow={openId} onActiveRowChange={(id) => setOpenId(id)} />

// a queue you swipe on a phone (the same actions are buttons in the pane)
const api = useRef(null);
<DataTable columns={requestColumns} rows={requests} apiRef={api} showHeader={false}
  swipeActions={{ start: { id: "approve", label: "Approve", icon: "check", tone: "var(--ts-success)" },
                  end: { id: "snooze", label: "Snooze", icon: "clock", tone: "var(--ts-warning)" } }}
  onSwipe={(row, action) => decide(row.id, action.id)}       // remove it from requests: its gap closes
  animateRows={{ exit: "collapse" }}                        // your own chip flies from api.current.getRowRect(id)
  concealedRows={landing}                                    // a restored row stays invisible until its chip lands
  rowProps={(row) => ({ "aria-label": `${row.unread ? "Unread. " : ""}${row.title}` })} />
